const fs = require('fs');
const data = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);

const n = data[0];
let darioWins = 0;

for (let i = 1, rodada = 0; rodada < n; rodada++, i += 2) {
  const d = data[i];
  const x = data[i + 1];
  const diff = (x - d + 5) % 5;

  if (diff === 1 || diff === 2) {
    darioWins++;
  }
}

console.log(darioWins > n - darioWins ? 'dario' : 'xerxes');
